/* Minimal stand-in for Bootstrap's JS (written for the offline capture). The
 * router UI uses bootstrap.Modal plus data-bs-toggle="collapse" / "dropdown".
 * Nothing is animated: elements toggle the "show" class and the same
 * show/shown/hide/hidden.bs.<component> events as Bootstrap are dispatched,
 * because some pages fill or reset form fields in those handlers. */
(function () {
  function fire(el, name) {
    const evt = new Event(name, { bubbles: true, cancelable: true });
    return el.dispatchEvent(evt);
  }
  function toggler(component) {
    const instances = new WeakMap();
    return class {
      constructor(el) { this._el = el; instances.set(el, this); }
      static getInstance(el) { return instances.get(el) || null; }
      static getOrCreateInstance(el) { return instances.get(el) || new this(el); }
      show() {
        const el = this._el;
        if (!el || el.classList.contains("show")) return;
        if (!fire(el, "show.bs." + component)) return;
        el.classList.add("show");
        fire(el, "shown.bs." + component);
      }
      hide() {
        const el = this._el;
        if (!el || !el.classList.contains("show")) return;
        if (!fire(el, "hide.bs." + component)) return;
        el.classList.remove("show");
        fire(el, "hidden.bs." + component);
      }
      toggle() {
        if (this._el && this._el.classList.contains("show")) this.hide(); else this.show();
      }
      dispose() {}
    };
  }
  const Modal = toggler("modal");
  const Collapse = toggler("collapse");
  const Dropdown = toggler("dropdown");
  document.addEventListener("click", function (evt) {
    const trigger = evt.target.closest && evt.target.closest("[data-bs-toggle], [data-bs-dismiss]");
    if (!trigger) return;
    const dismiss = trigger.getAttribute("data-bs-dismiss");
    if (dismiss === "modal") {
      const modal = trigger.closest(".modal");
      if (modal) Modal.getOrCreateInstance(modal).hide();
      return;
    }
    const kind = trigger.getAttribute("data-bs-toggle");
    const selector = trigger.getAttribute("data-bs-target") || trigger.getAttribute("href");
    if (kind === "collapse" && selector && selector.startsWith("#")) {
      document.querySelectorAll(selector).forEach((el) => Collapse.getOrCreateInstance(el).toggle());
    } else if (kind === "modal" && selector && selector.startsWith("#")) {
      const el = document.querySelector(selector);
      if (el) Modal.getOrCreateInstance(el).toggle();
    } else if (kind === "dropdown") {
      const menu = trigger.parentElement && trigger.parentElement.querySelector(".dropdown-menu");
      if (menu) Dropdown.getOrCreateInstance(menu).toggle();
    }
  });
  window.bootstrap = { Modal, Collapse, Dropdown };
})();
